{"cmd":"python3 - <<'PY'
import os, random, socket, subprocess, tempfile, time, json, signal
BIN='/workspace/artifacts/target/upf'
TD=tempfile.mkdtemp(prefix='upffuzz-')
cfg=os.path.join(TD,'config.json')
conf={
 'mode':'af_packet','access':{'ifname':'lo'},'core':{'ifname':'lo'},
 'cpiface':{'hostname':'','http_port':'0','dnn':'internet'},
 'n4_addr':'127.0.0.1','resp_timeout':'2s','read_timeout':15,'log_level':'error'}
open(cfg,'w').write(json.dumps(conf))
out=open(os.path.join(TD,'out'),'wb'); err=open(os.path.join(TD,'err'),'wb')
p=subprocess.Popen([BIN,'-config',cfg],stdout=out,stderr=err)
try:
  time.sleep(6.5)
  print('started',p.poll())
  r=random.Random(0x50fc)
  crashed=None
  seen=[]
  # systematically test message types with lengths including huge/truncated and malformed IE headers
  cases=[]
  for typ in list(range(1,101)):
    for ln in (0,1,2,3,4,7,8,12,16,255,256,65535):
      cases.append((typ,ln))
  # random deterministic cases
  for _ in range(500): cases.append((r.randrange(1,256),r.randrange(0,65536)))
  for i,(typ,ln) in enumerate(cases):
    if p.poll() is not None:
      crashed=i; break
    hdr=bytes([0x20,typ])+ln.to_bytes(2,'big')+i.to_bytes(3,'big')+b'\x00'
    # lengths 1..7 truncate, larger creates deterministic nested malformed data
    if ln<=8:
      body=bytes(r.randrange(256) for _ in range(ln))
    else:
      # Include IE type/length combinations, zero and oversized lengths, binary payloads.
      body=bytearray()
      while len(body)<ln:
        if r.random()<.5:
          body += r.randrange(256).to_bytes(2,'big')+r.randrange(65536).to_bytes(2,'big')
        else:
          body += bytes([r.randrange(256),r.randrange(256)])
      body=bytes(body[:ln])
    msg=hdr+body
    try:
      s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); s.settimeout(.03)
      s.sendto(msg,('127.0.0.1',8805))
      try: reply=s.recvfrom(65535); seen.append((i,typ,ln,reply[0].hex()))
      except socket.timeout: pass
      s.close()
    except OSError: pass
    if i%100==0: print('probe',i,'poll',p.poll())
  time.sleep(.3)
  print('done polls',p.poll(),'seen',len(seen),'last',seen[-5:])
finally:
  if p.poll() is None:
    p.terminate()
    try:p.wait(2)
    except subprocess.TimeoutExpired:p.kill();p.wait()
  out.close();err.close()
  print('rc',p.returncode)
  print('stdout tail:')
  print(open(os.path.join(TD,'out'),'rb').read()[-12000:].decode(errors='replace'))
  print('stderr:')
  print(open(os.path.join(TD,'err'),'rb').read().decode(errors='replace'))
  import shutil;shutil.rmtree(TD)
PY","workdir":"/workspace","yield_time_ms":30000,"max_output_tokens":30000}

